        { id: "kp06_q13", type: "choice", difficulty: 3, question: "判断完全平方数，横线处应填（ ）。\n<pre><code>for(int i=0;i<=N;i++)\n    if(________) cout<<N<<\"是完全平方数\";</code></pre>", options: ["i==N*N", "i*10==N", "i+i==N", "i*i==N"], answer: 3, explanation: "完全平方数满足 i*i==N。", source: "2024_06" },
        { id: "kp06_q14", type: "coding", difficulty: 2, question: "读入5个整数到数组，找出最大值。\n<p>输入：<code>3 7 2 9 5</code></p>\n<p>输出：<code>9</code></p>", starterCode: "#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5];\n    for(int i=0;i<5;i++) cin >> a[i];\n    // 找最大值\n    \n    return 0;\n}", testCases: [{ input: "3 7 2 9 5", expectedOutput: "9", description: "最大值9" }], referenceCode: "#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5];\n    for(int i=0;i<5;i++) cin >> a[i];\n    int mx=a[0];\n    for(int i=1;i<5;i++) if(a[i]>mx) mx=a[i];\n    cout << mx << endl;\n    return 0;\n}", explanation: "假设第一个最大，遍历比较更新。" },
        { id: "kp06_q15", type: "coding", difficulty: 2, question: "读入5个整数到数组，逆序输出（空格分隔）。\n<p>输入：<code>1 2 3 4 5</code></p>\n<p>输出：<code>5 4 3 2 1</code></p>", starterCode: "#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5];\n    for(int i=0;i<5;i++) cin >> a[i];\n    // 逆序输出\n    \n    return 0;\n}", testCases: [{ input: "1 2 3 4 5", expectedOutput: "5 4 3 2 1", description: "逆序输出" }], referenceCode: "#include <iostream>\nusing namespace std;\n\nint main() {\n    int a[5];\n    for(int i=0;i<5;i++) cin >> a[i];\n    for(int i=4;i>=0;i--){\n        if(i<4) cout << \" \";\n        cout << a[i];\n    }\n    cout << endl;\n    return 0;\n}", explanation: "从最后一个元素向前遍历。" }
